<section class="page-head"><span class="eyebrow">SUPER ADMIN</span><h1>Register Doctor</h1><p>Create a doctor account from the administration portal.</p></section><form class="form-card wide" method="post"><div class="grid2"><label>Name<input name="name" required></label><label>Phone<input name="phone" required></label><label>Email<input type="email" name="email" required></label><label>Aadhaar<input name="aadhaar_no" maxlength="12" required></label><label>PAN<input name="pan_no" maxlength="10" required></label><label>Specialization<select name="specialization_id" required><?php foreach($specializations as $s):?><option value="<?=$s['id']?>"><?=$s['name']?></option><?php endforeach?></select></label><label>Medical Registration No.<input name="medical_registration_no" required></label><label>Registration Council<input name="registration_council"></label><label>Experience Years<input type="number" name="experience_years"></label><label>Degree<input name="degree"></label><label>Degree Number<input name="degree_number"></label><label>Institute<input name="institute"></label><label>University<input name="university"></label><label>Passing Year<input type="number" name="passing_year"></label><label>Hospital<select name="hospital_id"><option value="">Select later</option><?php foreach($hospitals as $h):?><option value="<?=$h['id']?>"><?=$h['name']?></option><?php endforeach?></select></label><label>OPD Fee<input type="number" name="consultation_fee"></label><label>Video Fee<input type="number" name="video_fee"></label><label>Emergency Fee<input type="number" name="emergency_fee"></label></div><label>Bio<textarea name="bio"></textarea></label><?php include __DIR__.'/../address_fields.php';?><label>Temporary Password<input type="password" name="password" value="Doctor@123" required></label><button class="btn primary">Register Doctor</button></form>